api.github.com/repos/jonochocki/mission-control/commits/68b90402687dfc68cfe9112eed06c094795de05b/comments","commit":{"author":{"date":"2026-05-30T18:25:50Z","email":"wires_brogue3z@icloud.com","name":"Lucas Martin"},"comment_count":0,"committer":{"date":"2026-05-30T18:25:50Z","email":"wires_brogue3z@icloud.com","name":"Lucas Martin"},"message":"chore: verify Mission Control gateway compatibility with OpenClaw 2026.5.27","tree":{"sha":"57f84c13da93f3ec16f8add8ba66744fb765312f","url":"https://api.github.com/repos/jonochocki/mission-control/git/trees/57f84c13da93f3ec16f8add8ba66744fb765312f"},"url":"https://api.github.com/repos/jonochocki/mission-control/git/commits/68b90402687dfc68cfe9112eed06c094795de05b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/258319624?v=4","events_url":"https://api.github.com/users/lucas-martin-locki/events{/privacy}","followers_url":"https://api.github.com/users/lucas-martin-locki/followers","following_url":"https://api.github.com/users/lucas-martin-locki/following{/other_user}","gists_url":"https://api.github.com/users/lucas-martin-locki/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lucas-martin-locki","id":258319624,"login":"lucas-martin-locki","node_id":"U_kgDOD2WlCA","organizations_url":"https://api.github.com/users/lucas-martin-locki/orgs","received_events_url":"https://api.github.com/users/lucas-martin-locki/received_events","repos_url":"https://api.github.com/users/lucas-martin-locki/repos","site_admin":false,"starred_url":"https://api.github.com/users/lucas-martin-locki/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lucas-martin-locki/subscriptions","type":"User","url":"https://api.github.com/users/lucas-martin-locki","user_view_type":"public"},"html_url":"https://github.com/jonochocki/mission-control/commit/68b90402687dfc68cfe9112eed06c094795de05b","node_id":"C_