tegory\nin Docker/standalone deployments.","tree":{"sha":"a2ee0b7f323f69f59fec488d98032b05cc38526d","url":"https://api.github.com/repos/jonochocki/mission-control/git/trees/a2ee0b7f323f69f59fec488d98032b05cc38526d"},"url":"https://api.github.com/repos/jonochocki/mission-control/git/commits/14e605fbf3ef394a9ebc7c5e8528edd46f680874","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/93952610?v=4","events_url":"https://api.github.com/users/0xNyk/events{/privacy}","followers_url":"https://api.github.com/users/0xNyk/followers","following_url":"https://api.github.com/users/0xNyk/following{/other_user}","gists_url":"https://api.github.com/users/0xNyk/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/0xNyk","id":93952610,"login":"0xNyk","node_id":"U_kgDOBZmaYg","organizations_url":"https://api.github.com/users/0xNyk/orgs","received_events_url":"https://api.github.com/users/0xNyk/received_events","repos_url":"https://api.github.com/users/0xNyk/repos","site_admin":false,"starred_url":"https://api.github.com/users/0xNyk/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/0xNyk/subscriptions","type":"User","url":"https://api.github.com/users/0xNyk","user_view_type":"public"},"html_url":"https://github.com/jonochocki/mission-control/commit/14e605fbf3ef394a9ebc7c5e8528edd46f680874","node_id":"C_kwDOSsbBo9oAKDE0ZTYwNWZiZjNlZjM5NGE5ZWJjN2M1ZTg1MjhlZGQ0NmY2ODA4NzQ","parents":[{"html_url":"https://github.com/jonochocki/mission-control/commit/5d197ee11797dfe95a97987227421c3b8e0e5cf5","sha":"5d197ee11797dfe95a97987227421c3b8e0e5cf5","url":"https://api.github.com/repos/jonochocki/mission-control/commits/5d197ee11797dfe95a97987227421c3b8e0e5cf5"}],"sha":"14e605fbf3ef394a9ebc7c5e8528edd46f680874","url":"https://api.github.com/repos/jonochocki/mission-control/commits/14e605fbf3ef394a9ebc7c5e8528edd46f680874"},{"author":{"avatar_url":