valves consume more memory and do not improve wall time. The exact completion and publication gates are unchanged.","tree":{"sha":"a51f57b32a961d63a5297bd27986ba9bf6cfc431","url":"https://api.github.com/repos/bio-ontology-research-group/kobayashi-marust/git/trees/a51f57b32a961d63a5297bd27986ba9bf6cfc431"},"url":"https://api.github.com/repos/bio-ontology-research-group/kobayashi-marust/git/commits/0728e332bc149921e80d6bcca22364aca85a0d91","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/362161?v=4","events_url":"https://api.github.com/users/leechuck/events{/privacy}","followers_url":"https://api.github.com/users/leechuck/followers","following_url":"https://api.github.com/users/leechuck/following{/other_user}","gists_url":"https://api.github.com/users/leechuck/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/leechuck","id":362161,"login":"leechuck","node_id":"MDQ6VXNlcjM2MjE2MQ==","organizations_url":"https://api.github.com/users/leechuck/orgs","received_events_url":"https://api.github.com/users/leechuck/received_events","repos_url":"https://api.github.com/users/leechuck/repos","site_admin":false,"starred_url":"https://api.github.com/users/leechuck/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/leechuck/subscriptions","type":"User","url":"https://api.github.com/users/leechuck","user_view_type":"public"},"html_url":"https://github.com/bio-ontology-research-group/kobayashi-marust/commit/0728e332bc149921e80d6bcca22364aca85a0d91","node_id":"C_kwDOSvLNj9oAKDA3MjhlMzMyYmMxNDk5MjFlODBkNmJjY2EyMjM2NGFjYTg1YTBkOTE","parents":[{"html_url":"https://github.com/bio-ontology-research-group/kobayashi-marust/commit/2db41a15d56e4982b423d754f33e2d6c98cdd0ca","sha":"2db41a15d56e4982b423d754f33e2d6c98cdd0ca","url":"https://api.github.com/repos/bio-ontology-research-group/kobayashi-marust/commits/2db41a15d56e4982b423d754f33e